HTML_TEMPLATE = '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PE 距离衰减与观测方向对比</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#203047;font:14px/1.55 system-ui,"Microsoft YaHei",sans-serif}header{background:#fff;padding:18px 24px;border-bottom:1px solid #dde3ec}h1{margin:0;font-size:22px}p{margin:8px 0}.layout{display:grid;grid-template-columns:220px minmax(0,1fr) 300px;min-height:90vh}nav,aside{padding:18px;background:#fff}nav{border-right:1px solid #dde3ec}aside{border-left:1px solid #dde3ec;overflow-wrap:anywhere}main{padding:20px;min-width:0}button,select,input{font:inherit;padding:8px;border:1px solid #cdd6e2;border-radius:6px;background:#fff}button{cursor:pointer}nav button{width:100%;text-align:left;margin-top:7px;border:0;overflow-wrap:anywhere}nav button.active{background:#e9effa;color:#2454a0}nav input{width:100%}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:12px 0 25px}.card{background:#fff;border:1px solid #d9e0ea;border-radius:9px;overflow:hidden}.card h3{margin:0;padding:11px;font-size:15px;border-bottom:1px solid #edf0f5}.viewport{height:310px;background:white;cursor:zoom-in}.viewport img{width:100%;height:100%;object-fit:contain;display:block}.labels{max-height:230px;overflow:auto;padding:10px}.labels table{border-collapse:collapse;width:100%;font-size:12px}.labels td,.labels th{padding:6px;border-bottom:1px solid #e8edf4;text-align:left}.labels th{position:sticky;top:0;background:white}.audit{padding:10px;color:#5c6b80;font-size:12px;border-top:1px solid #edf0f5}.muted{color:#68788e}.box{margin:18px 0;padding-bottom:12px;border-bottom:1px solid #e2e7ef}.box h3{margin:0 0 8px;font-size:15px}.box ul,.box ol{margin:0;padding-left:20px}.box li{margin-bottom:7px}.badge{background:#edf2f9;border-radius:5px;padding:3px 7px;margin-right:8px;font-size:12px}dialog{width:min(95vw,1600px);max-height:95vh;padding:16px;border:0;border-radius:10px}dialog::backdrop{background:#172333b3}dialog img{width:100%;display:block}.dialogbar{display:flex;justify-content:space-between;margin-bottom:12px}.instruction{margin:16px 0;white-space:pre-wrap}.hint{font-size:12px;color:#68788e}.sectiontitle{font-size:17px;margin:18px 0 8px}details{margin-top:10px}pre{white-space:pre-wrap;font-size:12px}\n@media(max-width:1250px){.layout{grid-template-columns:180px minmax(0,1fr)}aside{grid-column:2;display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid{min-width:750px}.row-scroll{overflow-x:auto}}\n@media(max-width:650px){.layout{display:block}nav{max-height:200px;overflow:auto}main{padding:12px}aside{display:block}.viewport{height:270px}}\n</style></head><body><header><h1>PE 距离衰减与观测方向对比</h1><p id="subtitle" class="muted">初始化统一四向 · 单向／三向导航 · τ＝1／3／6 米 · 无 DINO / SAM</p></header><div class="layout"><nav><input id="search" placeholder="搜索轨迹或指令" aria-label="搜索"><div id="folders"></div></nav><main><div class="controls"><strong id="name"></strong><span id="status" class="badge"></span><label>楼层 <select id="floor"></select></label><label>地图 <select id="layer"><option value="rgb_map">RGB</option><option value="passability_map">可通行性</option></select></label></div><p id="instruction" class="instruction"></p><p class="hint">τ 越小，近处权重越强。相同观测方式的三个 τ 共用相同成图逻辑，重点比较下方 S 段的区域标签与分数。点击地图放大。</p><div id="maps"></div></main><aside><div id="objects" class="box"></div><div id="regions" class="box"></div><div id="top10" class="box"></div><div class="box"><h3>实验说明</h3><p>物体与区域列表由 VLM 从指令提取；本版未执行物体检测，因此物体列表不代表现场已识别物体。</p><p>PE 保留每段四帧采样、原有聚合及 CLS＋末端池化距离衰减。VLM 每 16 步分别审核六组，目标提取只做一次。</p></div></aside></div><dialog id="modal"><div class="dialogbar"><strong id="modalname"></strong><button id="close">关闭</button></div><img id="large" alt="放大地图"></dialog><script type="application/json" id="data">__CASES__</script><script>\n\'use strict\';const CASES=JSON.parse(document.getElementById(\'data\').textContent),$=id=>document.getElementById(id);let selected=0;\nfunction el(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e}\nfunction folders(){const q=$(\'search\').value.toLowerCase();$(\'folders\').replaceChildren();CASES.forEach((c,i)=>{if(!(c.name+\' \'+c.instruction).toLowerCase().includes(q))return;const b=el(\'button\',\'▸ \'+c.name);b.className=i===selected?\'active\':\'\';b.onclick=()=>{selected=i;render()};$(\'folders\').append(b)})}\nfunction targets(id,title,items,ordered=false){const box=$(id);box.replaceChildren(el(\'h3\',title));const list=el(ordered?\'ol\':\'ul\');for(const t of items){const li=el(\'li\',typeof t===\'string\'?t:t.name);if(t.modifiers?.length)li.append(el(\'div\',t.modifiers.join(\'；\')));list.append(li)}box.append(list);if(!items.length)box.append(el(\'p\',\'未提取到\'))}\nfunction render(){folders();const c=CASES[selected];if(!c){$(\'maps\').textContent=\'等待第一条轨迹的初始地图保存。\';return}$(\'name\').textContent=c.name;$(\'subtitle\').textContent=\'初始化统一四向 · 单向／三向导航 · τ＝\'+[...new Set(c.variants.map(v=>v.tau))].sort((a,b)=>a-b).join(\'／\')+\' 米 · 无 DINO / SAM\';$(\'instruction\').textContent=c.instruction;$(\'status\').textContent=`${c.complete?\'已完成\':\'进行中\'} · ${c.steps} 步`;\n targets(\'objects\',\'VLM 指令物体列表\',c.instruction_objects);targets(\'regions\',\'VLM 指令区域列表\',c.instruction_regions);targets(\'top10\',\'指令相关区域 Top10\',c.room_top10,true);\n const old=$(\'floor\').value;$(\'floor\').replaceChildren();const heights=[...new Set(c.variants.flatMap(v=>v.floors.map(f=>f.index)))].sort((a,b)=>a-b);for(const n of heights){const o=el(\'option\',`第 ${n+1} 层`);o.value=n;$(\'floor\').append(o)}if(heights.includes(Number(old)))$(\'floor\').value=old;const fi=Number($(\'floor\').value),root=$(\'maps\');root.replaceChildren();\n for(const directions of [1,3]){const h=el(\'h2\',directions===1?\'单向：当前第一视角\':\'三向：前方、左方、右方\');h.className=\'sectiontitle\';root.append(h);const scroll=el(\'div\');scroll.className=\'row-scroll\';const grid=el(\'div\');grid.className=\'grid\';const variants=c.variants.filter(v=>v.directions===directions).sort((a,b)=>a.tau-b.tau);for(const v of variants){const card=el(\'section\');card.className=\'card\';card.append(el(\'h3\',`τ＝${v.tau} m`));const f=v.floors.find(f=>f.index===fi);if(f&&f.maps[$(\'layer\').value]){const viewport=el(\'div\');viewport.className=\'viewport\';const image=el(\'img\');image.src=f.maps[$(\'layer\').value];image.alt=`${c.name} ${directions}向 τ=${v.tau}`;viewport.append(image);viewport.onclick=()=>{$(\'large\').src=image.src;$(\'modalname\').textContent=image.alt;$(\'modal\').showModal()};card.append(viewport)}else card.append(el(\'p\',\'该楼层尚未保存地图\'));\n const labels=el(\'div\');labels.className=\'labels\';const table=el(\'table\'),head=el(\'tr\');for(const label of [\'段\',\'区域标签\',\'分数\',\'步数\'])head.append(el(\'th\',label));table.append(head);for(const s of v.segments.filter(s=>s.floor===fi)){const row=el(\'tr\');for(const value of [`S${s.id}`,s.region_type||\'待判定\',Number.isFinite(s.score)?s.score.toFixed(3):\'—\',`${s.start_step}–${s.end_step}`])row.append(el(\'td\',value));table.append(row)}labels.append(table);card.append(labels);const audit=el(\'div\');audit.className=\'audit\';audit.textContent=`VLM：${({off_route:\'偏航\',no_supported_deviation:\'未发现明确偏航\',uncertain:\'证据不足\',not_reviewed:\'尚未复核\'})[v.audit.decision]||v.audit.decision} · 复核至 ${v.reviewed_through_step} 步`;const detail=el(\'details\');detail.append(el(\'summary\',\'查看证据与 PE 详情\'),el(\'pre\',JSON.stringify({audit:v.audit,segments:v.segments.filter(s=>s.floor===fi)},null,2)));audit.append(detail);card.append(audit);grid.append(card)}scroll.append(grid);root.append(scroll)} }\n$(\'search\').oninput=folders;$(\'floor\').onchange=render;$(\'layer\').onchange=render;$(\'close\').onclick=()=>$(\'modal\').close();render();\n</script></body></html>\n'


def load_original():
    module=types.ModuleType('_original_depth_label')
    module.__file__=str(Path(__file__).resolve());sys.modules[module.__name__]=module
    source=zlib.decompress(base64.b64decode(ORIGINAL_SOURCE)).decode()
    filename='<uploaded_original_depth_label>'
    linecache.cache[filename]=(len(source),None,source.splitlines(True),filename)
    exec(compile(source,filename,'exec'),module.__dict__)
    return module


class NoDetector:
    def predict(self,*a,**k):return []
    def close(self):pass


class TauMatcher:
    def __init__(self,client,tau):self.client,self.tau=client,float(tau)
    def score(self,packets,categories):
        return self.client.score([dict(p,_comparison_tau=self.tau) for p in packets],categories)


def install_dynamic_tau(original):
    parent=original.DepthPEEncoder
    class DynamicTauEncoder(parent):
        def score(self,images,categories):
            taus={float(p.get('_comparison_tau',self.depth_args.depth_tau)) for p in images}
            if len(taus)>1:raise ValueError('One PE request must use one tau')
            if taus:
                tau=taus.pop()
                if not math.isfinite(tau) or tau<=0:raise ValueError('Invalid comparison tau')
                self.depth_args.depth_tau=tau
            # Parent cache key contains tau and the paired RGB/depth packet.
            # All original CLS biases and attention-pooling biases stay intact.
            return super().score(images,categories)
    original.DepthPEEncoder=DynamicTauEncoder


def thicken_display_walls(original,rgb,extra_pixels):
    """Change only the draw assignment, never the geometry/blocker wall mask."""
    from scipy.ndimage import binary_dilation
    def stroke(mask):
        return binary_dilation(mask,iterations=extra_pixels) if extra_pixels else mask
    class DisplayStroke(ast.NodeTransformer):
        def visit_Assign(self,node):
            for target in node.targets:
                if (isinstance(target,ast.Subscript) and isinstance(target.value,ast.Name)
                    and target.value.id in ('image','values') and isinstance(target.slice,ast.Name)
                    and target.slice.id=='wall_mask'):
                    target.slice=ast.Call(func=ast.Name(id='_comparison_wall_stroke',ctx=ast.Load()),
                                         args=[target.slice],keywords=[])
            return node
    import textwrap
    for owner,name,globals_ in ((rgb.FloorMap,'render',rgb.__dict__),
                                (original,'image_geometry',original.__dict__)):
        fn=getattr(owner,name)
        source=inspect.getsource(fn)
        tree=ast.parse(textwrap.dedent(source));tree=DisplayStroke().visit(tree)
        globals_['_comparison_wall_stroke']=stroke
        exec(compile(ast.fix_missing_locations(tree),'<display_wall_stroke>','exec'),globals_)
        setattr(owner,name,globals_[name])


def capture(env,raw,depth_key,extra_yaws):
    import quaternion
    sim=env.sim;state=copy.deepcopy(sim.get_agent_state())
    old=getattr(sim,'_prev_sim_obs',None)
    views=[(raw,state)]
    try:
        for yaw in extra_yaws:
            rotation=state.rotation*quaternion.from_rotation_vector([0.,math.radians(yaw),0.])
            obs=sim.get_observations_at(state.position,rotation,keep_agent_at_new_pose=True)
            views.append((obs,copy.deepcopy(sim.get_agent_state())))
    finally:
        sim.get_agent(0).set_state(state,reset_sensors=False,infer_sensor_states=False)
        if hasattr(sim,'_prev_sim_obs'):sim._prev_sim_obs=old
    return views


def replay_class(original):
    class ComparisonReplay(original.LabelReplay):
        def project(self,raw,state,detect,capture_front=False):
            # First-person RGB/depth remains the PE/VLM sampled observation.
            bundles=self.bundle[:self.direction_count]
            clouds=[original.LabelReplay.project(self,obs,pose,False,
                     capture_front=capture_front and i==0) for i,(obs,pose) in enumerate(bundles)]
            if len(clouds)==1:return clouds[0]
            return (np.concatenate([c[0] for c in clouds]),np.concatenate([c[1] for c in clouds]),
                    [v for c in clouds for v in c[2]],[v for c in clouds for v in c[3]],
                    np.concatenate([c[4] for c in clouds]))

        def initialize_bundle(self,views):
            import quaternion
            raw,state=views[0]
            self.floors.append(self.rgb.FloorMap(state.position[1]))
            clouds=[original.LabelReplay.project(self,obs,pose,False,capture_front=i==0)
                    for i,(obs,pose) in enumerate(views)]
            self.floors[0].add_views(clouds)
            position=np.asarray(state.position).copy()
            self.current_position=position.copy()
            self.current_forward=-quaternion.as_rotation_matrix(state.rotation)[:,2]
            self.floors[0].route.append((0,position[[0,2]]))
            self.route.append(dict(step=0,floor=0,position=position.tolist()))
            self.rooms.record(0,0,position,raw[self.rgb_key],**self.front_metadata.get(0,{}))
            self.add_node(('start',0),0,0,position,'start')
    return ComparisonReplay


IMAGE_CACHE={}
def image_data(path):
    stamp=path.stat();key=str(path);signature=(stamp.st_mtime_ns,stamp.st_size)
    cached=IMAGE_CACHE.get(key)
    if cached is None or cached[0]!=signature:
        with Image.open(path) as source:
            image=source.convert('RGB');image.thumbnail((1400,1400),Image.Resampling.LANCZOS)
            buffer=io.BytesIO();image.save(buffer,format='WEBP',quality=92)
        IMAGE_CACHE[key]=(signature,'data:image/webp;base64,'+base64.b64encode(buffer.getvalue()).decode())
    return IMAGE_CACHE[key][1]


def snapshot(folder,job,instruction,inventory,replays,complete,atomic):
    variants=[]
    for replay in replays:
        floors=[]
        for index,floor in enumerate(replay.floors):
            maps={}
            for kind in ('rgb_map','passability_map'):
                path=replay.folder/('%s_%02d.png'%(kind,index+1))
                if path.is_file():maps[kind]=str(path.relative_to(folder))
            floors.append(dict(index=index,height=floor.height,maps=maps))
        variants.append(dict(key=replay.variant_key,directions=replay.direction_count,tau=replay.tau,
            floors=floors,segments=copy.deepcopy(replay.rooms.segments),
            audit=copy.deepcopy(replay.deviation),reviewed_through_step=replay.last_review))
    result=dict(name=job['name'],baseline_success=job['success'],instruction=instruction,
        instruction_objects=inventory['objects'],instruction_regions=inventory['regions'],
        room_top10=[replays[0].rooms.categories[i] for i in range(10)],
        variants=variants,complete=complete,steps=max(r.step for r in replays),
        tau_unit='meters',depth_formula='max(exp(-strength*d/tau), minimum)',
        pe_sampling='unchanged original: four first-person frames per trajectory segment',
        detectors_enabled=False,initial_views=4,vlm_review_interval=16)
    atomic(folder/'comparison.json',result)


def write_html(path,cases):
    payload=json.dumps(cases,ensure_ascii=False,separators=(',',':')).replace('<',r'\u003c')
    html=HTML_TEMPLATE.replace('__CASES__',payload)
    temp=path.with_suffix('.tmp');temp.write_text(html,encoding='utf-8');temp.replace(path)


def refresh_reports(output,jobs):
    """Update the single self-contained report from all available snapshots."""
    cases=[]
    for job in jobs:
        folder=output/('success' if job['success'] else 'failure')/job['name']
        data_path=folder/'comparison.json'
        if not data_path.is_file():continue
        data=json.loads(data_path.read_text(encoding='utf-8'))
        try:
            for variant in data['variants']:
                for floor in variant['floors']:
                    floor['maps']={k:image_data(folder/p) for k,p in floor['maps'].items()}
        except OSError:continue
        cases.append(data)
    write_html(output/'report.html',cases)


def arguments(original):
    extra=__import__('argparse').ArgumentParser(add_help=False)
    extra.add_argument('--pe_taus',type=float,nargs=3,default=[1.,3.,6.])
    extra.add_argument('--wall_extra_pixels',type=int,default=1)
    extra.add_argument('--report_only',action='store_true')
    opts,rest=extra.parse_known_args()
    # Keep every original model/API/dataset option and its validation.
    if '--output_path' not in rest:rest+=['--output_path','results/test_pe_map_compare_50']
    sys.argv=[sys.argv[0]]+rest
    args=original.arguments()
    args.pe_taus=opts.pe_taus;args.wall_extra_pixels=opts.wall_extra_pixels;args.report_only=opts.report_only
    if (len(set(args.pe_taus))!=3 or any(not math.isfinite(x) or x<=0 for x in args.pe_taus)
        or args.wall_extra_pixels<0):raise ValueError('Need three distinct positive taus and nonnegative wall pixels')
    args.pe_taus.sort()
    if (not all(math.isfinite(v) for v in (args.pe_depth_tau,args.pe_depth_strength,args.pe_depth_min_weight))
        or args.pe_depth_tau<=0 or args.pe_depth_strength<0 or not 0<args.pe_depth_min_weight<=1):
        raise ValueError('Invalid PE depth parameters')
    return args


def main():
    original=load_original()
    if '--worker' in sys.argv:
        install_dynamic_tau(original)
        return original.depth_worker()
    args=arguments(original)
    os.environ['CUDA_VISIBLE_DEVICES']=args.gpu;os.chdir(original.ROOT)
    import room_similarity as rooms
    output=Path(args.output_path).expanduser().resolve();output.mkdir(parents=True,exist_ok=True)
    jobs=original.select_jobs(args)
    cached=output/'.cache';cached.mkdir(exist_ok=True)
    config=dict(original_sha256=ORIGINAL_SHA256,settings={k:v for k,v in vars(args).items()
                 if k not in ('report_only','list_only','output_path')},jobs=jobs)
    config_path=cached/'config.json'
    if config_path.is_file() and json.loads(config_path.read_text(encoding='utf-8'))!=config:
        raise ValueError('Settings changed: use a new output directory')
    rooms.atomic_json(config_path,config)
    refresh_reports(output,jobs)
    if args.report_only or args.list_only:return 0
    for path in (Path(args.room_checkpoint),Path(args.room_pe_repo)/'core/vision_encoder/pe.py'):
        if not path.exists():raise ValueError('Missing PE checkpoint/source: '+str(path))
    import governor_topdown_map_nodes as base
    import rgb_mapping as rgb
    thicken_display_walls(original,rgb,args.wall_extra_pixels)
    Replay=replay_class(original)
    client=base.APIVLM(args);pe=None
    try:
        for job in jobs:
            folder=output/('success' if job['success'] else 'failure')/job['name'];folder.mkdir(parents=True,exist_ok=True)
            marker=folder/'comparison.json'
            if marker.is_file() and json.loads(marker.read_text(encoding='utf-8')).get('complete'):continue
            rows,truncated=original.load_actions(job['actions_file'],args.max_steps)
            env=None;replays=[];instruction='';inventory=None
            try:
                env,sensors,episode=original.make_environment(args,job,len(rows))
                provided=[r['instruction'] for r in rows if isinstance(r.get('instruction'),str) and r['instruction'].strip()]
                fallback=getattr(episode,'instruction','')
                instruction=provided[0] if provided else str(getattr(fallback,'instruction_text',fallback))
                if not instruction.strip():raise ValueError('Missing instruction')
                if any(' '.join(t.split())!=' '.join(instruction.split()) for t in provided):raise ValueError('Instruction changes')
                target_path=cached/(job['name']+'_targets.json')
                if target_path.is_file():
                    saved=json.loads(target_path.read_text(encoding='utf-8'))
                    if saved['instruction']!=instruction:raise ValueError('Instruction cache mismatch')
                    inventory=saved['inventory']
                else:
                    inventory=original.extract_targets(client,base,instruction)
                    rooms.atomic_json(target_path,dict(instruction=instruction,inventory=inventory))
                if pe is None:pe=original.DepthPEClient(args,original.ROOMS)
                for directions in (1,3):
                    for tau in args.pe_taus:
                        key='views%d_tau_%g'%(directions,tau)
                        replay=Replay(env,sensors,args,NoDetector(),TauMatcher(pe,tau),client,base,rgb,rooms,
                                      folder,job,instruction,inventory)
                        replay.folder=folder/key;replay.folder.mkdir(exist_ok=True)
                        replay.cache_folder=cached/job['name']/key;replay.cache_folder.mkdir(parents=True,exist_ok=True)
                        replay.direction_count=directions;replay.tau=tau;replay.variant_key=key
                        replays.append(replay)
                raw=env.reset()
                views=capture(env,raw,replays[0].depth_key,(90.,-90.,180.))
                for replay in replays:
                    replay.initialize_bundle(views);replay.update_maps();replay.save(truncated=truncated)
                snapshot(folder,job,instruction,inventory,replays,False,rooms.atomic_json)
                for step,row in enumerate(rows,1):
                    if env.episode_over:break
                    raw=env.step({'action':original.ACTION_KEYS[row['action']]})
                    final=row['action']==0 or env.episode_over or step==len(rows)
                    views=capture(env,raw,replays[0].depth_key,(90.,-90.))
                    for replay in replays:
                        replay.step=step;replay.bundle=views;replay.fuse(raw,final)
                        if final:replay.flush_pending()
                        if final or step%5==0 or step%16==0:
                            replay.update_maps()
                            if step%16==0:replay.review()
                            replay.save(truncated=truncated)
                    if final or step%5==0 or step%16==0:
                        snapshot(folder,job,instruction,inventory,replays,False,rooms.atomic_json)
                        print('[pe-compare] %s step=%d; six variants updated; no detectors'%(job['name'],step),flush=True)
                    if final:break
                for replay in replays:
                    replay.flush_pending();replay.update_maps();replay.save(final=True,truncated=truncated)
                snapshot(folder,job,instruction,inventory,replays,True,rooms.atomic_json)
            except original.APIUnavailable as exc:
                print('[pe-compare] pending API: '+str(exc),flush=True)
            finally:
                if env is not None:env.close()
                refresh_reports(output,jobs)
    finally:
        if pe is not None:pe.close()
        client.close();refresh_reports(output,jobs)
    print('[pe-compare] saved '+str(output/'report.html'),flush=True)
    return 0


if __name__=='__main__':
    try:raise SystemExit(main())
    except KeyboardInterrupt:
        print('[pe-compare] interrupted; last saved maps and HTML remain',file=sys.stderr)
        raise SystemExit(130)
